      "content": "[build-system]\nrequires = [\"setuptools>=68\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"clawock\"\nversion = \"0.4.2\"\ndescription = \"Investment workflows for AI agents: evidence, opposing cases, and outcomes checked by Python.\"\nreadme = \"README.md\"\nrequires-python = \">=3.11\"\nlicense = { file = \"LICENSE\" }\nauthors = [{ name = \"Shengyu Li\" }]\nkeywords = [\n    \"agent\", \"llm\", \"decision-workflow\", \"harness\", \"portfolio\", \"provenance\",\n    \"reconciliation\", \"evidence\", \"audit\", \"mcp\", \"plugins\", \"strategy\",\n    \"walk-forward\",\n]\n# Trove classifiers are how PyPI's own search and category filters see this\n# package. Without them it is unlisted everywhere a prospective user would\n# browse, and nothing local ever shows it: `pip install -e .` never renders a\n# project page.\nclassifiers = [\n    \"Development Status :: 4 - Beta\",\n    \"Intended Audience :: Developers\",\n    \"Intended Audience :: Financial and Insurance Industry\",\n    \"License :: OSI Approved :: MIT License\",\n    \"Operating System :: OS Independent\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n    \"Topic :: Office/Business :: Financial :: Investment\",\n    \"Topic :: Software Development :: Libraries :: Python Modules\",\n    \"Typing :: Typed\",\n]\n\n# The one place dependencies are declared. They used to live in nine workflow\n# files as drifting `pip install` lines — `requests` in seven, `requests numpy`\n# in one, `requests pytest pytest-cov numpy Pillow` in another. The comment\n# above that last one already records the cost: a missing numpy once aborted\n# pytest collection and silently stopped enforcing the whole suite while the\n# run still looked green.\ndependencies = [\n    # 2.32.4 is the floor past both advisories on this line: CVE-2024-35195\n    # (redirect header leak, fixed 2.32.0) and CVE-2024-47081 (.netrc\n    # credential leak, fixed 2.32.4). Nothing here turns off trust_env.\n    \"requests>=2.32.4\",\n    # numpy was in an optional `compute` extra while `portfolio/risk.py` — the\n    # module behind the packaged `portfolio-risk` command — imported it at the\n    # top level unconditionally. A clean `pip install clawock` therefore shipped\n    # a first-class command that raised ImportError on its first line. It is\n    # required because it already was; the metadata was the part that was wrong.\n    \"numpy>=1.26\",\n    # Required for the same reason, from 2026-08-30: the evaluation and risk\n    # lanes (shrinkage estimators, hierarchical clustering, optimisation,\n    # distribution tails, eigendecomposition) are not code that should be\n    # hand-rolled to keep a wheel small. The alternative on offer was a package\n    # where half the analysis commands fail on a clean install, which is worse\n    # for \"install decision intelligence into any agent\" than a bigger download.\n    \"scipy>=1.11\",\n]\n\n[project.optional-dependencies]\n# `compute = []` lived here from 2026-08-30, when numpy and scipy became\n# required and the extra was kept as an alias so its three call sites would not\n# break. That trade stopped being cheap once the composite action's own docs\n# told users to pass a `compute` selector \"when the job needs the heavier\n# dependency set\" while the heavier set was nothing at all (#1321). The call sites now ask\n# for what they actually need, which is the market-data fallback below.\n#\n# yfinance is the last hop of both quote chains — tier 4 for HK\n# (market_data/hk_analysis.py, after Tencent / Eastmoney / stooq) and provider 5\n# for US (market_data/us_quotes.py). Both import it lazily inside a try, so a\n# missing package does not crash: it silently deletes the bottom of the fallback\n# chain, which is exactly the hop that only ever runs when the others are\n# already rate-limited (#1325). It is an extra rather than a required\n# dependency because that chain has four other hops and yfinance drags pandas\n# behind it; it is *declared* because a fallback nobody can install is not one.\nmarket = [\"yfinance>=0.2\"]\nevaluation = [\"matplotlib>=3.8\"]\n# Screenshot and social-card validation. 13.0.0 is the floor because\n# `validate-sidecar` fully decodes artifacts with `Image.open`, which sniffs every\n# registered format, and every earlier release still carries open decoder\n# advisories in OSV (12.3.0 has 41, including the BMP RLE amplification and the\n# MIC/TarIO infinite-loop DoS fixed only in 13.0.0).\nimaging = [\"Pillow>=13.0.0\"]\n# Search Console visibility pull (ops/growth/crawl_visibility.py). Declared here\n# for the same reason as everything else in this table: a version pinned in a\n# workflow line is a second source of truth that drifts unseen.\nseo = [\"google-auth>=2.30\"]\n# Building and checking a distribution. Here rather than in the release workflow\n# for the same reason as everything else in this table: a version pinned in a\n# workflow line is a second source of truth that drifts unseen.\nrelease = [\"build>=1.2\", \"twine>=5\"]\n# Everything the test suite needs to *collect*, not just to pass.\n# PyYAML is here for the same reason as the rest: the public-entry-point test\n# parses .github/ISSUE_TEMPLATE/config.yml as structured data rather than\n# substring-matching it, and a test module that cannot import does not fail —\n# it stops the whole suite at collection while the run still looks like it ran.\ntest = [\"pytest>=8\", \"pytest-cov>=5\", \"pytest-xdist>=3\", \"Pillow>=13.0.0\", \"PyYAML>=6\"]\n\n[project.urls]\nHomepage = \"https://github.com/KCNyu/clawock\"\nDocumentation = \"https://kcnyu.github.io/clawock/\"\nSource = \"https://github.com/KCNyu/clawock\"\nIssues = \"https://github.com/KCNyu/clawock/issues\"\n# PyPI renders project URLs as the sidebar of the project page, and a\n# `Changelog` key is the one downstream tooling looks for by name when it wants\n# to show a user what a pending upgrade contains. Without it, \"what changed\n# between 0.1.0 and 0.1.1\" had no answer anywhere a package consumer could see.\nChangelog = \"https://github.com/KCNyu/clawock/blob/master/CHANGELOG.md\"\nEvidence = \"https://kcnyu.github.io/clawock/#reflect\"\n\n[project.scripts]\nclawock = \"clawock.cli:main\"\nclawock-brief-watchdog = \"clawock.harness.brief_watchdog:main\"\nclawock-report-watchdog = \"clawock.harness.report_watchdog:main\"\nclawock-intraday-watchdog = \"clawock.harness.intraday_watchdog:main\"\nclawock-cron-heartbeat = \"clawock.automation.cron_heartbeat:main\"\nclawock-workflow-outcomes = \"clawock.automation.workflow_outcomes:main\"\nclawock-intraday-delta = \"clawock.harness.intraday_delta:main\"\nclawock-gold-fetch = \"clawock.market_data.gold.fetch:main\"\nclawock-gold-update = \"clawock.market_data.gold.update:main\"\nclawock-influencer-scan = \"clawock.automation.influencer:main\"\nclawock-brief-fallback = \"clawock.automation.brief_fallback:main\"\nclawock-news-digest = \"clawock.automation.news_digest:main\"\nclawock-weekly-review = \"clawock.automation.weekly_review:main\"\n\n[tool.setuptools]\npackage-dir = {\"\" = \"src\"}\n# The installable surface is the `clawock` package. It started as a single\n# py-module at the repo root, which built a wheel that crashed on import the\n# moment it was installed outside the source checkout: the module reached into\n# scripts/data/ through a sys.path hack for code the wheel did not contain.\n# `pip install -e .` hid that completely, because editable installs leave the\n# source tree on sys.path. Anything the CLI imports has to live in here.\n#\n# scripts/ is still deliberately unpackaged — it is the operator-side\n# implementation of this desk, and the coupling there is inside modules rather\n# than between them.\n#\n# Discovered rather than listed. `packages = [\"clawock\"]` is an *exact* list in\n# setuptools, so `clawock.providers` and `clawock.tools` were silently left out of\n# the wheel the moment they were added — the rule two paragraphs up, broken by the\n# next two PRs that obeyed it in spirit. A pattern brings a new subpackage in by\n# construction; a list brings it in only if someone remembers.\n[tool.setuptools.packages.find]\nwhere = [\"src\"]\ninclude = [\"clawock*\"]\n\n[tool.setuptools.package-data]\nclawock = [\n    \"context/manifest.json\",\n    \"config/*.schema.json\",\n    \"workflows/packs/*/*.json\",\n    \"workflows/packs/*/*.md\",\n    \"workflows/packs/*/references/*.md\",\n    \"workflows/packs/*/references/*.json\",\n    \"workflows/packs/*/assets/*.json\",\n    \"workflows/packs/*/agents/*.yaml\",\n]\n\n[tool.ruff]\ntarget-version = \"py311\"\n\n[tool.ruff.lint]\n# Correctness only — see the \"Lint Python\" step in .github/workflows/ci.yml.\nselect = [\"F\", \"E9\"]\n"
